<?php $options = wuai_sluyu_get_options(); $article_id = is_singular('post') ? get_queried_object_id() : 0; ?>
<aside class="sluyu-sidebar sluyu-sidebar-reference">
<?php if ($article_id) : $author_id = (int) get_post_field('post_author', $article_id); $author = get_userdata($author_id); ?>
    <section class="sluyu-author-card"><h2>关于作者 <a href="<?php echo esc_url(get_author_feed_link($author_id)); ?>" title="订阅作者文章"><?php echo wuai_sluyu_icon('heart-add-line'); ?> 订阅</a></h2><div class="sluyu-author-profile"><?php echo get_avatar($author_id, 60); ?><div><a href="<?php echo esc_url(get_author_posts_url($author_id)); ?>"><?php echo esc_html($author ? $author->display_name : '作者'); ?></a><small>文章作者</small></div></div><div class="sluyu-author-stats"><div><span>文章</span><strong><?php echo esc_html(count_user_posts($author_id, 'post', true)); ?></strong></div><div><span>评论</span><strong><?php echo esc_html(get_comments(['user_id' => $author_id, 'status' => 'approve', 'count' => true])); ?></strong></div></div>
        <div class="sluyu-author-posts"><?php $author_posts = get_posts(['post_type' => 'post', 'post_status' => 'publish', 'has_password' => false, 'author' => $author_id, 'numberposts' => 4]); foreach ($author_posts as $author_post) : ?><a href="<?php echo esc_url(get_permalink($author_post)); ?>"><span>[文章]</span> <?php echo esc_html($author_post->post_title); ?></a><?php endforeach; ?></div><a class="sluyu-author-all" href="<?php echo esc_url(get_author_posts_url($author_id)); ?>">Ta的全部文章</a>
    </section>
    <?php if (!post_password_required($article_id) && $options['article_show_toc'] === '1') : ?><section class="sluyu-toc-card" hidden><h2>文章目录</h2><nav class="sluyu-toc" aria-label="文章目录"></nav></section><?php endif; ?>
    <?php wuai_sluyu_download_card($article_id, true); ?>
<?php endif; ?>
    <section class="sluyu-recent-card"><h2>最近更新</h2><?php $recent = new WP_Query(['post_type' => 'post', 'post_status' => 'publish', 'has_password' => false, 'posts_per_page' => 5, 'orderby' => 'modified', 'ignore_sticky_posts' => true, 'no_found_rows' => true]); $rank = 0; if ($recent->have_posts()) : while ($recent->have_posts()) : $recent->the_post(); $rank++; ?><a class="sluyu-recent-item" href="<?php the_permalink(); ?>"><?php if ($rank <= 3) : ?><b class="sluyu-recent-rank rank-<?php echo absint($rank); ?>">TOP<?php echo absint($rank); ?></b><?php endif; ?><img src="<?php echo esc_url(wuai_sluyu_image(get_the_ID(), 'thumbnail')); ?>" alt="" loading="lazy"><span><strong><?php the_title(); ?></strong><time><?php echo esc_html(get_the_date('n月j日')); ?></time></span></a><?php endwhile; wp_reset_postdata(); else : ?><p class="sluyu-empty">暂无已发布文章</p><?php endif; ?></section>
</aside>
